import '@testing-library/jest-dom/vitest'

import { configureStore } from '@reduxjs/toolkit'
import { render, screen } from '@testing-library/react'
import { Provider } from 'react-redux'
import { MemoryRouter } from 'react-router-dom'
import { describe, expect, it, vi } from 'vitest'

vi.mock('../services/apiClient', () => ({
  apiClient: {
    get: vi.fn().mockResolvedValue({
      data: { items: [], page: 1, pageSize: 20, totalCount: 0, totalPages: 0 },
    }),
    post: vi.fn().mockResolvedValue({ data: {} }),
  },
  // The family dashboard stays in its loading state for routing assertions.
  threePortalApi: { getFamilyDashboard: vi.fn(() => new Promise(() => {})) },
  // Head-transfer banner (members): nothing waiting.
  familyLifecycleApi: { getIncomingHeadTransfer: vi.fn().mockResolvedValue({ data: '' }) },
  refreshSession: vi.fn(),
}))

// Mock assets so Vitest doesn't choke on binary files
vi.mock('../assets/logo.png',      () => ({ default: 'logo.png' }))
vi.mock('../assets/Loging.webp',   () => ({ default: 'loging.webp' }))
vi.mock('../assets/Register.webp', () => ({ default: 'register.webp' }))
vi.mock('../styles/auth-shell.css', () => ({}))

import authReducer, { signedIn } from '../store/slices/authSlice'
import { AppRoutes } from './AppRouter'

function renderRoute(
  path: string,
  role?: 'DOCTOR' | 'ADMIN' | 'FAMILY_HEAD' | 'MEMBER' | 'ONBOARDING',
  doctorVerification: 'PENDING' | 'VERIFIED' = 'VERIFIED',
  familyHeadVerification: 'PENDING' | 'VERIFIED' = 'VERIFIED',
) {
  const store = configureStore({ reducer: { auth: authReducer } })

  if (role) {
    store.dispatch(
      signedIn({
        id: `${role.toLowerCase()}-synthetic-01`,
        name: 'Synthetic User',
        role,
        verificationStatus: role === 'DOCTOR' ? doctorVerification : undefined,
        familyHeadVerificationStatus: (role === 'FAMILY_HEAD' || role === 'ONBOARDING') ? familyHeadVerification : undefined,
      }),
    )
  }

  return render(
    <Provider store={store}>
      <MemoryRouter initialEntries={[path]}>
        <AppRoutes />
      </MemoryRouter>
    </Provider>,
  )
}

describe('AppRoutes', () => {
  it('redirects unauthenticated visitors to login', () => {
    renderRoute('/cases')
    // New design: main landmark labelled "Sign in", section heading "Welcome back"
    expect(screen.getByRole('main', { name: /sign in/i })).toBeInTheDocument()
  })

  it('blocks family users from doctor case routes and redirects to dashboard', () => {
    renderRoute('/cases', 'FAMILY_HEAD')

    // Redirected to the family dashboard, which starts by loading GET /dashboard/family.
    expect(screen.getByText(/loading your family dashboard/i)).toBeInTheDocument()
    expect(screen.queryByRole('heading', { name: /triage cases/i })).not.toBeInTheDocument()
  })

  it('shows verified doctors the live triage case queue', async () => {
    renderRoute('/cases', 'DOCTOR')
    expect(screen.getByRole('heading', { name: /triage cases/i })).toBeInTheDocument()
    expect(await screen.findByText('No matching cases')).toBeInTheDocument()
    expect(screen.queryByText('FV-TR-1048')).not.toBeInTheDocument()
  })

  it('shows verified doctors the live approval queue', async () => {
    renderRoute('/approvals', 'DOCTOR')

    expect(await screen.findByText('No cases awaiting approval')).toBeInTheDocument()
    expect(screen.queryByText('FV-TR-1048')).not.toBeInTheDocument()
  })

  it('blocks unverified doctors from clinical routes', async () => {
    renderRoute('/approvals', 'DOCTOR', 'PENDING')
    expect(await screen.findByRole('heading', { name: /doctor verification/i })).toBeInTheDocument()
  })

  it('allows administrators to view audit activity', () => {
    renderRoute('/audit', 'ADMIN')
    expect(screen.getByRole('heading', { name: /audit log/i })).toBeInTheDocument()
  })

  it('routes an unlinked family account into required onboarding', () => {
    renderRoute('/dashboard', 'ONBOARDING')

    expect(screen.getByRole('heading', { name: /create your family profile/i })).toBeInTheDocument()
  })

  it('blocks unverified family heads and directs to verification status', async () => {
    renderRoute('/dashboard', 'ONBOARDING', 'VERIFIED', 'PENDING')

    expect(await screen.findByRole('heading', { name: /family head verification/i })).toBeInTheDocument()
  })

  it('exposes public family registration', () => {
    renderRoute('/register')
    // New design: main landmark labelled "Create account"
    expect(screen.getByRole('main', { name: /create account/i })).toBeInTheDocument()
  })

  it('exposes public doctor registration', () => {
    renderRoute('/register/doctor')
    // DoctorRegisterPage: main landmark "Doctor registration", heading "Create your account"
    expect(screen.getByRole('main', { name: /doctor registration/i })).toBeInTheDocument()
  })

  it('allows administrators to view family head verification queue', async () => {
    renderRoute('/family-head-verification', 'ADMIN')

    expect(await screen.findByRole('heading', { name: /family head verification/i })).toBeInTheDocument()
  })

  it('shows the Family Head the blueprint menu in order, with Emergency Help', async () => {
    renderRoute('/dashboard', 'FAMILY_HEAD')

    const nav = await screen.findByRole('navigation', { name: /primary navigation/i })
    const labels = Array.from(nav.querySelectorAll('a')).map((link) => link.textContent)
    expect(labels).toEqual([
      'Dashboard', 'My Family', 'Health Records', 'Symptoms & Triage', 'My Doctor', 'Appointments', 'Privacy & Access',
    ])
    expect(screen.getByRole('button', { name: 'Emergency Help' })).toBeInTheDocument()
  })

  it('shows the Adult Member the blueprint menu without family administration', async () => {
    renderRoute('/dashboard', 'MEMBER')

    const nav = await screen.findByRole('navigation', { name: /primary navigation/i })
    const labels = Array.from(nav.querySelectorAll('a')).map((link) => link.textContent)
    expect(labels).toEqual(['Dashboard', 'My Health', 'Appointments', 'Symptoms & Triage', 'My Family', 'My Doctor', 'Privacy'])
  })

  it('shows the Doctor one Calendar tab and the blueprint menu', async () => {
    renderRoute('/cases', 'DOCTOR')

    const nav = await screen.findByRole('navigation', { name: /primary navigation/i })
    const labels = Array.from(nav.querySelectorAll('a')).map((link) => link.textContent)
    expect(labels).toEqual(['Dashboard', 'Calendar', 'My Families', 'Triage Cases', 'Approvals', 'Profile & Availability'])
  })

  it('shows the Clinic Admin the governance menu', async () => {
    renderRoute('/audit', 'ADMIN')

    const nav = await screen.findByRole('navigation', { name: /primary navigation/i })
    const labels = Array.from(nav.querySelectorAll('a')).map((link) => link.textContent)
    expect(labels).toEqual(['Dashboard', 'Doctor Verification', 'Users', 'Audit Log', 'Safety & System'])
  })
})

